  LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);header.setPadding(Ui.dp(this,22),Ui.dp(this,12),Ui.dp(this,22),Ui.dp(this,8));
  ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.icon_lock);logo.setContentDescription(null);header.addView(logo,new LinearLayout.LayoutParams(Ui.dp(this,26),Ui.dp(this,26)));
  TextView brand=new TextView(this);brand.setText("Yuki Lockdown");brand.setTextSize(19);brand.setTypeface(android.graphics.Typeface.create("sans-serif-medium",android.graphics.Typeface.NORMAL));brand.setTextColor(Ui.WHITE);brand.setPadding(Ui.dp(this,10),0,0,0);header.addView(brand,new LinearLayout.LayoutParams(0,-2,1));
  TextView badge=new TextView(this);badge.setText("LOCAL");badge.setTextSize(10);badge.setLetterSpacing(.12f);badge.setTextColor(Ui.BLUE);badge.setPadding(Ui.dp(this,10),Ui.dp(this,7),Ui.dp(this,10),Ui.dp(this,7));badge.setBackground(Ui.shape(this,0xff1b2d40,12));header.addView(badge);root.addView(header);
  ScrollView scroll=new ScrollView(this);scroll.setClipToPadding(false);scroll.setVerticalScrollBarEnabled(false);FrameLayout center=new FrameLayout(this);body=Ui.column(this);body.setPadding(Ui.dp(this,20),Ui.dp(this,8),Ui.dp(this,20),Ui.dp(this,24));FrameLayout.LayoutParams cp=new FrameLayout.LayoutParams(Math.min(getResources().getDisplayMetrics().widthPixels,Ui.dp(this,640)),-2,Gravity.CENTER_HORIZONTAL);center.addView(body,cp);LinearLayout pageBody=body;center.addOnLayoutChangeListener((v,left,top,right,bottom,oldLeft,oldTop,oldRight,oldBottom)->{int width=Math.min(right-left,Ui.dp(this,640));if(width>0&&pageBody.getLayoutParams().width!=width){pageBody.getLayoutParams().width=width;pageBody.requestLayout();}});scroll.addView(center);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
