  for(int index=0;index<destinations.length;index++){final String name=destinations[index];boolean selected=page.equals(name);LinearLayout item=Ui.column(this);item.setGravity(Gravity.CENTER);item.setPadding(Ui.dp(this,2),Ui.dp(this,8),Ui.dp(this,2),Ui.dp(this,6));item.setMinimumHeight(Ui.dp(this,62));item.setBackground(Ui.ripple(this,selected?0xff23354b:0xff111925,18));item.addView(new NavIcon(this,index,selected?Ui.BLUE:Ui.MUTED),new LinearLayout.LayoutParams(Ui.dp(this,23),Ui.dp(this,23)));TextView label=Ui.text(item,labels[index],11,selected?Ui.BLUE:Ui.MUTED);label.setGravity(Gravity.CENTER);label.setPadding(0,Ui.dp(this,4),0,0);item.setContentDescription(name+(selected?", selected":""));item.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_YES);item.setFocusable(true);item.setSelected(selected);label.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(0,-2,1);np.setMargins(Ui.dp(this,2),0,Ui.dp(this,2),0);nav.addView(item,np);item.setOnClickListener(v->{page=name;config=store.load();render();});}
  root.addView(nav);setContentView(root);if(!store.error.isEmpty())Ui.text(body,store.error,16,Ui.BLUE);
  switch(page){case "Apps"->apps();case "Websites"->websites();case "Schedules"->schedules();case "Settings"->settings();default->home();}
