 private void timePicker(EditText field){field.setFocusable(false);field.setClickable(true);field.setContentDescription(field.getText()+", choose time");field.setOnClickListener(v->{int minute=Ui.time(field.getText().toString());new TimePickerDialog(this,(picker,h,m)->{field.setText(Ui.time(h*60+m));field.setContentDescription(field.getText()+", choose time");},minute/60,minute%60,true).show();});}
 private void previewYuki(){Dialog d=new Dialog(this);d.requestWindowFeature(Window.FEATURE_NO_TITLE);View content=Intervention.create(this,"bedtime","Bedtime preview","Darling, it’s bedtime. Your feed can wait. ♡",1,()->d.dismiss(),()->{d.dismiss();Device.talk(this);},()->d.dismiss(),true);d.setContentView(content);if(d.getWindow()!=null){d.getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(android.graphics.Color.TRANSPARENT));d.getWindow().setDimAmount(0);}d.show();if(d.getWindow()!=null)d.getWindow().setLayout(-1,-1);}
 private void bypass(boolean strict){for(Rules.Schedule s:config.schedules)if(s.strict&&s.occurrence(ZonedDateTime.now())!=null)strict=true;int wait=Math.max(config.bypassWaitSeconds,strict?60:0);LinearLayout l=form();Ui.text(l,"You retain control. Pause restrictions for "+config.bypassMinutes+" minutes. Your reason stays on this screen and is not saved.",16,Ui.WHITE);EditText reason=Ui.field(l,"Why do you need a break?","",false);AlertDialog d=new AlertDialog.Builder(this).setTitle("Emergency bypass").setView(l).setNegativeButton("Cancel",null).setPositiveButton("Wait…",null).create();long until=SystemClock.elapsedRealtime()+wait*1000L;Runnable countdown=new Runnable(){public void run(){if(!d.isShowing())return;long left=Math.max(0,(until-SystemClock.elapsedRealtime()+999)/1000);Button b=d.getButton(-1);b.setText(left>0?"Wait "+left+"s":"Confirm break");b.setEnabled(left==0);if(left>0)handler.postDelayed(this,250);}};d.setOnShowListener(v->{Ui.sheet(d);d.getButton(-1).setOnClickListener(w->{if(SystemClock.elapsedRealtime()<until)return;if(reason.getText().toString().trim().length()<4){toast("Enter a short reason first.");return;}try{store.bypass(config.bypassMinutes);d.dismiss();toast("Break started. Your rules resume automatically.");render();}catch(Exception e){toast("Could not save the bypass. You can still edit your rules.");}});countdown.run();});d.show();}
